$$\begin{array}{l}
  {{f^{\prime}{(x)} = \frac{d}{\mathit{dx}}{({x^{2} + 1})}^{- 1}} = {- 2x{(x^{2} + 1)}^{- 2}}\qquad\begin{array}{l}
